insert into categories(slug,name,description) values
('casual-wear','Casual Wear','Everyday pieces cut for ease.'),
('formal-wear','Formal Wear','Tailoring with a modern line.'),
('street-style','Street Style','Relaxed shapes, considered details.'),
('outerwear','Outerwear','Coats and jackets for every season.'),
('accessories','Accessories','Leather goods and finishing touches.') on conflict do nothing;
insert into products(slug,sku,name,description,price_cents,sale_price_cents,category_id,tags,badge,materials,care,published) select 'beige-bomber-jacket','BEIGE-BOMBER-JACKET','Beige Bomber Jacket','A lightweight bomber in brushed cotton twill.',18900,null,id,'{jacket,bomber}','BESTSELLER','Responsibly sourced natural fibres.','Dry clean or cold wash; dry flat.',true from categories where slug='outerwear' on conflict do nothing;
insert into product_variants(product_id,size,color_name,color_hex,sku,stock) select p.id,s,'Sand','#D8C8B0','BEIGE-BOMBER-JACKET-'||s||'-'||upper(left('Sand',3)),20 from products p, unnest(array['S','M','L','XL']) s where p.slug='beige-bomber-jacket' on conflict do nothing;
insert into product_variants(product_id,size,color_name,color_hex,sku,stock) select p.id,s,'Charcoal','#262421','BEIGE-BOMBER-JACKET-'||s||'-'||upper(left('Charcoal',3)),20 from products p, unnest(array['S','M','L','XL']) s where p.slug='beige-bomber-jacket' on conflict do nothing;
